class Solution {
public:
    vector<int> selfDividingNumbers(int left, int right) {
        vector<int> res;
        for (int v = left; v <= right; v++) {
            int x = v;
            bool ok = true;
            while (x > 0 && ok) {
                int d = x % 10;
                if (d == 0 || v % d != 0) ok = false;
                x /= 10;
            }
            if (ok) res.push_back(v);
        }
        return res;
    }
};
